def link_chat_runs_to_threads(apps, schema_editor):
    """Existing chat turns belong to the chat session they ran in."""
    Run = apps.get_model("research", "ResearchAgentRun")
    for run in Run.objects.filter(role="main-assistant", thread__isnull=True):
        run.thread_id = run.session_id
        run.save(update_fields=["thread"])


